    // --- TAB SWITCHING LOGIC ---
    const tabLive = document.getElementById('tabLive');
    const tabCalc = document.getElementById('tabCalc');
    const viewLive = document.getElementById('viewLive');
    const viewCalc = document.getElementById('viewCalc');
