async function initCesium() {
    // Initialize Cesium Viewer with Realistic Earth
    window.viewer = new Cesium.Viewer('cesiumContainer', {
        imageryProvider: new Cesium.ArcGisMapServerImageryProvider({
            url: 'https://services.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer'
        }),
        baseLayerPicker: false,
        geocoder: false,
        homeButton: true,
        infoBox: true,
        selectionIndicator: true,
        navigationHelpButton: false,
        sceneModePicker: false,
        animation: false,
        timeline: false,
        fullscreenButton: false,
        requestRenderMode: false // Allow continuous rendering for smooth tracking
    });

    // Hide Cesium logo/credit for prototype cleanliness
    viewer.cesiumWidget.creditContainer.style.display = 'none';

    try {
        const response = await fetch(TLE_API_URL);
        const data = await response.json();

        const now = new Date();

        data.tles.forEach(sat => {
            const satrec = satellite.twoline2satrec(sat.line1, sat.line2);

            // Calculate 90-minute orbital trajectory
            let positions = [];
            for (let i = 0; i <= 90; i++) {
                const time = new Date(now.getTime() + i * 60000);
                const posVel = satellite.propagate(satrec, time);
                if (posVel.position) {
                    const gmst = satellite.gstime(time);
                    const posGd = satellite.eciToGeodetic(posVel.position, gmst);
                    positions.push(Cesium.Cartesian3.fromDegrees(
                        satellite.degreesLong(posGd.longitude),
                        satellite.degreesLat(posGd.latitude),
                        posGd.height * 1000
                    ));
                }
            }

            const currentPosAndVel = satellite.propagate(satrec, now);

            if (currentPosAndVel.position && positions.length > 0) {
                const gmst = satellite.gstime(now);
                const positionGd = satellite.eciToGeodetic(currentPosAndVel.position, gmst);
                const longitude = satellite.degreesLong(positionGd.longitude);
                const latitude = satellite.degreesLat(positionGd.latitude);
                const height = positionGd.height * 1000; // to meters

                const isDebris = sat.name.includes('DEB');
                const objType = isDebris ? 'Space Debris' : 'Active Satellite';

                const entity = viewer.entities.add({
                    name: sat.name,
                    position: Cesium.Cartesian3.fromDegrees(longitude, latitude, height),
                    point: {
                        pixelSize: 8,
                        color: Cesium.Color.fromCssColorString('#00ffff'), // glowing cyan
                        outlineColor: Cesium.Color.WHITE,
                        outlineWidth: 2,
                    },
                    polyline: {
                        positions: positions,
                        width: 2,
                        material: Cesium.Color.fromCssColorString('#00ffff').withAlpha(0.4)
                    },
                    label: {
                        text: sat.name,
                        font: '12pt Inter',
                        fillColor: Cesium.Color.WHITE,
                        style: Cesium.LabelStyle.FILL_AND_OUTLINE,
                        outlineWidth: 2,
                        verticalOrigin: Cesium.VerticalOrigin.BOTTOM,
                        pixelOffset: new Cesium.Cartesian2(0, -9)
                    },
                    description: `
                        <div style="padding: 10px; font-family: Inter, sans-serif;">
                            <table style="width: 100%; text-align: left; border-collapse: collapse;">
                                <tr style="border-bottom: 1px solid rgba(255,255,255,0.2);">
                                    <th style="padding: 5px 0;">Type</th>
                                    <td style="padding: 5px 0; color: #aaa;">${objType}</td>
                                </tr>
                                <tr style="border-bottom: 1px solid rgba(255,255,255,0.2);">
                                    <th style="padding: 5px 0;">Altitude</th>
                                    <td style="padding: 5px 0; color: #aaa;">${(height/1000).toFixed(2)} km</td>
                                </tr>
                                <tr>
                                    <th style="padding: 5px 0;">Risk Status</th>
                                    <td style="padding: 5px 0; color: #aaa;">Active Tracking</td>
                                </tr>
                            </table>
                        </div>
                    `
                });

                satelliteEntities[sat.name] = entity;
            }
        });

    } catch (error) {
        console.error("Error loading TLEs for Cesium:", error);
    }
}

