const btnRetrograde = document.getElementById('btnRetrograde');
const btnAuthorize = document.getElementById('btnAuthorize');

let currentOriginalDist = 0;
let currentOriginalPcStr = "0.00e+00";
let isPrograde = true;

// Toggle Burn Direction
